var CORK_TEXTS = [
  '拔塞过程：木塞相对瓶口基准线的位置（三个阶段）',
  'u = x/h',
  'u = 0',
  'u = 1/2',
  'u = 1',
  'x = 0',
  'x = h/2',
  'x = h',
  'h',
  '瓶口基准线（水平）',
  'u = 1 时木塞底部到达瓶口基准线',
  '示意：木塞长度 = h，u = 0 时塞顶与瓶口齐平；三阶段位移依次为 0、h/2、h',
  '塞底距基准线 = h',
  '塞底距基准线 = h/2',
  '塞底与基准线齐平'
];
const visual = {
  prepare: function (input) {
    var out = [];
    for (var i = 0; i < CORK_TEXTS.length; i++) {
      out.push({ kind: 'text', payload: CORK_TEXTS[i] });
    }
    return out;
  },
  render: function (input, metrics) {
    var W = (input && input.viewport && input.viewport.widthDu) || 960;
    var H = (input && input.viewport && input.viewport.heightDu) || 600;
    var baseY = H * 0.50;
    var corkH = H * 0.18;
    var IW = 54, WT = 12, CW = 46;
    var wallBottom = baseY + corkH + H * 0.085;
    var cxs = [W * 0.20, W * 0.50, W * 0.80];
    var paths = [];
    var children = [];
    var pid = 0;
    function addPath(commands, opts) {
      var id = 'p' + (pid++);
      paths.push({ id: id, commands: commands });
      var node = { type: 'path', pathId: id };
      if (opts) { for (var k in opts) { node[k] = opts[k]; } }
      children.push(node);
      return id;
    }
    function rect(x, y, w, h) {
      return visualSdk.polyline([[x, y], [x + w, y], [x + w, y + h], [x, y + h], [x, y]]);
    }
    function seg(x1, y1, x2, y2) {
      return visualSdk.polyline([[x1, y1], [x2, y2]]);
    }
    var i, j, k, cx, lx, rx;
    for (i = 0; i < 3; i++) {
      cx = cxs[i];
      lx = cx - IW / 2 - WT;
      rx = cx + IW / 2;
      addPath(rect(lx, baseY, WT, wallBottom - baseY), { fill: '#dbe9f6', stroke: '#3d6fa5', strokeWidth: 1.4 });
      addPath(rect(rx, baseY, WT, wallBottom - baseY), { fill: '#dbe9f6', stroke: '#3d6fa5', strokeWidth: 1.4 });
      addPath(seg(lx - 4, baseY, rx + WT + 4, baseY), { stroke: '#3d6fa5', strokeWidth: 3 });
    }
    addPath(seg(W * 0.05, baseY, W * 0.95, baseY), { stroke: '#c0392b', strokeWidth: 2, strokeDasharray: [9, 6] });
    var us = [0, 0.5, 1];
    for (j = 0; j < 3; j++) {
      cx = cxs[j];
      var top = baseY - corkH * us[j];
      addPath(rect(cx - CW / 2, top, CW, corkH), { fill: '#e6c9a0', stroke: '#8a5a2b', strokeWidth: 1.6 });
      for (k = 1; k <= 3; k++) {
        var ty = top + corkH * k / 4;
        addPath(seg(cx - CW / 2 + 7, ty, cx + CW / 2 - 7, ty), { stroke: '#b98b5e', strokeWidth: 1 });
      }
    }
    var xdim = cxs[0] - IW / 2 - WT - 26;
    addPath(seg(xdim, baseY, xdim, baseY + corkH), { stroke: '#4a5a6a', strokeWidth: 1.2 });
    addPath(seg(xdim - 5, baseY + 10, xdim, baseY), { stroke: '#4a5a6a', strokeWidth: 1.2 });
    addPath(seg(xdim, baseY, xdim + 5, baseY + 10), { stroke: '#4a5a6a', strokeWidth: 1.2 });
    addPath(seg(xdim - 5, baseY + corkH - 10, xdim, baseY + corkH), { stroke: '#4a5a6a', strokeWidth: 1.2 });
    addPath(seg(xdim, baseY + corkH, xdim + 5, baseY + corkH - 10), { stroke: '#4a5a6a', strokeWidth: 1.2 });
    addPath(seg(xdim, baseY + corkH, cxs[0] - IW / 2 - WT, baseY + corkH), { stroke: '#8899aa', strokeWidth: 1, strokeDasharray: [4, 4] });
    function mOf(idx) {
      if (metrics && metrics[idx] && typeof metrics[idx] === 'object') { return metrics[idx]; }
      return null;
    }
    function mk(idx, x, y, size, color) {
      var node = { type: 'label', text: CORK_TEXTS[idx], x: x, y: y, fontSize: size, fill: color || '#22303f', anchor: 'middle' };
      var m = mOf(idx);
      if (m) {
        if (typeof m.width === 'number') { node.width = m.width; }
        else if (typeof m.w === 'number') { node.width = m.w; }
        if (typeof m.height === 'number') { node.height = m.height; }
        else if (typeof m.h === 'number') { node.height = m.h; }
      }
      return node;
    }
    children.push(mk(0, W / 2, H * 0.055, 20));
    children.push(mk(1, W / 2, H * 0.115, 24));
    var uY = baseY - corkH - H * 0.055;
    for (i = 0; i < 3; i++) { children.push(mk(2 + i, cxs[i], uY, 18)); }
    var xY = wallBottom + H * 0.045;
    var dY = wallBottom + H * 0.085;
    for (i = 0; i < 3; i++) {
      children.push(mk(5 + i, cxs[i], xY, 14));
      children.push(mk(12 + i, cxs[i], dY, 11, '#3a4a5a'));
    }
    children.push(mk(8, xdim - 15, baseY + corkH / 2, 15));
    children.push(mk(9, W * 0.70, baseY - H * 0.022, 12, '#c0392b'));
    children.push(mk(10, W / 2, H * 0.915, 13));
    children.push(mk(11, W / 2, H * 0.95, 12, '#3a4a5a'));
    return {
      schemaVersion: 1,
      sceneId: 'cork-pull-stages',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: paths,
      root: { type: 'group', children: children }
    };
  }
};
